memberdef.initializer:
                                             = frameCaller -> {
    char[] ach = ((StringHandle) frameCaller.popStack()).getValue();
    CONSOLE_LOG.log(ach, false);
    CONSOLE_OUT.print(ach);
    CONSOLE_OUT.flush();
    return Op.R_NEXT;
}

